window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"LbKfjlBTxsE","speaker":"Antonio Tajani","role":"Prime Minister","country":"Italy","region":"Europe","url":"https://www.youtube.com/watch?v=LbKfjlBTxsE","date":"20260924","title":"🇮🇹 Italy - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":904,"words":2136,"counts":{"claims":26,"promises":5,"attacks":4},"topics":[{"topic":"UN reform","share":0.3384,"seconds":306},{"topic":"AI regulation","share":0.1388,"seconds":125},{"topic":"Russia-Ukraine","share":0.0876,"seconds":79},{"topic":"Iran","share":0.074,"seconds":67},{"topic":"Africa infrastructure","share":0.0732,"seconds":66},{"topic":"Israel-Gaza","share":0.0695,"seconds":63},{"topic":"European Union","share":0.0687,"seconds":62},{"topic":"Global peace","share":0.068,"seconds":61},{"topic":"Lebanon","share":0.0673,"seconds":61},{"topic":"Ceremony","share":0.0146,"seconds":13}],"timeline":[[0,63,null],[64,126,"Global peace"],[126,206,"UN reform"],[207,276,"UN reform"],[278,344,"Africa infrastructure"],[345,425,"Russia-Ukraine"],[425,488,"Israel-Gaza"],[490,551,"Lebanon"],[552,619,"Iran"],[621,682,"AI regulation"],[683,747,"AI regulation"],[747,840,"UN reform"],[841,905,"UN reform"],[912,974,"European Union"],[975,988,"Ceremony"]],"stances":{"Global peace":"Antonio Tajani asserts that Italy rejects the normalization of war and chooses to uphold the rule of law and political dialogue over force.","UN reform":"Antonio Tajani argues that the United Nations must actively reform its instruments and overcome paralysis to build a new framework of rules and cooperation.","Africa infrastructure":"Antonio Tajani argues that the EU and West should act as bridges rather than walls, promoting initiatives like IMEC and the Mattei Plan to foster equal partnerships with Africa in sectors such as agriculture, energy, and health.","Russia-Ukraine":"Antonio Tajani states that Italy supports Ukraine and condemns Russia's aggression while calling for a ceasefire as a step toward European security.","Israel-Gaza":"Antonio Tajani asserts that peace in the Middle East requires a two-state solution, calls for consolidating the truce and allowing unobstructed humanitarian aid while demanding Hamas disarmament, and highlights Italy's specific humanitarian contributions to Gaza.","Lebanon":"Italy highlights its historical and ongoing contributions to peace in southern Lebanon through UNIFIL and training, while expressing commitment to continue supporting the region despite the mission's mandate ending.","Iran":"Antonio Tajani calls for Iran to abandon nuclear threats and aggressive policies while urging an end to attacks on shipping in the Red Sea and Russia's actions in the Black Sea.","AI regulation":"Antonio Tajani argues that politics must lead the technological revolution to prevent new inequalities, dependencies, and forms of domination caused by artificial intelligence.","European Union":"Antonio Tajani describes the European Union as a deliberate political achievement born from cooperation that secured peace and prosperity, emphasizing that this peace requires daily responsibility and resolve to maintain.","Ceremony":"Antonio Tajani expresses a firm commitment to not giving up and receives thanks from the host."},"claims":[{"t":105,"quote":"Ukraine, the Middle East, the Gulf, Sudan, and the Sahel are not separate crises, nor are trade wars, AI competition, hybrid attacks, and their economic and social Nor is terrorism in all of its many forms, which we continue to fight in every corner of the world.","topic":"Global peace","kind":"fact"},{"t":130,"quote":"The world order that emerged after World War II is coming It was an imperfect order. It did not prevent wars, injustice, or But today, the world balance has been disrupted","topic":"UN reform","kind":"fact"},{"t":207,"quote":"The United Nations remains the most universal place for pursuing this aspiration.","topic":"UN reform","kind":"fact"},{"t":223,"quote":"It is precisely when the world is divided that the value of dialogue grows rather than diminish diminishes.","topic":"UN reform","kind":"fact"},{"t":305,"quote":"The Mattei Plan now involves 18 countries and is built on a simple idea, not to decide for Africa, but to decide with Africa.","topic":"Africa infrastructure","kind":"number"},{"t":369,"quote":"Italy has made its choice. Italy stands for rules, dialogue, and policy.","topic":"Russia-Ukraine","kind":"self_credit"},{"t":375,"quote":"That is why we have condemned and continue to condemn Russia's aggression against Ukraine.","topic":"Russia-Ukraine","kind":"fact"},{"t":436,"quote":"Peace can come only through a two-state solution, two peoples, two states.","topic":"Israel-Gaza","kind":"fact"},{"t":443,"quote":"In Gaza, the truce has slowed the fighting but has not yet ended the suffering.","topic":"Israel-Gaza","kind":"fact"},{"t":457,"quote":"From the very beginning, Italy has mobilized the very best of its humanitarian capabilities through food for Gaza.","topic":"Israel-Gaza","kind":"self_credit"},{"t":464,"quote":"We have delivered food and essential supplies provided by our farmers.","topic":"Israel-Gaza","kind":"self_credit"},{"t":469,"quote":"We have welcomed and cared for wounded and vulnerable children.","topic":"Israel-Gaza","kind":"self_credit"},{"t":472,"quote":"We have opened our universities and research centers to young Palestinians because a future state also needs a future generation of In Lebanon, the stakes affect the entire region. The Washington agreement of 26 June opened a door.","topic":"Israel-Gaza","kind":"self_credit"},{"t":498,"quote":"For decades, Italian troops have served the cause of peace in southern Lebanon through UNIFIL and have helped train the Lebanese armed forces.","topic":"Lebanon","kind":"fact"},{"t":518,"quote":"61 active conflicts mean that war is advancing even far from the television","topic":"Lebanon","kind":"number"},{"t":561,"quote":"Attacks on shipping in the Red Sea must cease as uh must uh Russia's reckless attacks in the Black Sea on shipments of Ukrainian grain destined for Africa.","topic":"Iran","kind":"fact"},{"t":577,"quote":"They drive up the cost of energy, grain, bread, and fertilizers.","topic":"Iran","kind":"fact"},{"t":653,"quote":"The great inventions of the past took centuries to transform the world. Artificial intelligence is doing so in a matter of years.","topic":"AI regulation","kind":"fact"},{"t":679,"quote":"Falsifying and manipulating reality will become ever more easier.","topic":"AI regulation","kind":"fact"},{"t":690,"quote":"Pope Leo the XIV in the encyclical Magnifica Humanitas reminded us that no algorithm can take the place of human","topic":"AI regulation","kind":"fact"},{"t":716,"quote":"Artificial intelligence can open up possibilities that today are unimaginable in medicine, for example, research, education, manufacturing, and environmental protection","topic":"AI regulation","kind":"fact"},{"t":773,"quote":"The United Nations was founded in 1945 out of a world in ruins, a world that had learned a simple truth.","topic":"UN reform","kind":"fact"},{"t":782,"quote":"81 years later, that lesson is more relevant than","topic":"UN reform","kind":"number"},{"t":882,"quote":"We are among the leading contributors to the United Nations budget and among the top contributing troop contributing countries.","topic":"UN reform","kind":"fact"},{"t":888,"quote":"Uh we place men and women, our resources, and our expertise at the service of peace in UNIFIL and in every mission in which we participate.","topic":"UN reform","kind":"fact"},{"t":915,"quote":"my generation was born on a continent that had endured two world wars and then went on to experience the longest period of peace in its history.","topic":"European Union","kind":"fact"}],"promises":[{"t":379,"quote":"We will continue to support Ukraine um for as long as necessary","topic":"Russia-Ukraine","kind":"promise"},{"t":510,"quote":"we will continue to play our part even after the mission's mandate has come to an end.","topic":"Lebanon","kind":"promise"},{"t":593,"quote":"we are working side by side with United Nations Rome-based agencies, making available the best Italian expertise from agriculture and food production to satellite technologies that help reduce the use of land, water, and pesticides.","topic":"Iran","kind":"promise"},{"t":799,"quote":"With this conviction, Italy will continue to advocate for a universal moratorium on the death penalty, a cause rooted in civilization.","topic":"UN reform","kind":"promise"},{"t":975,"quote":"And we will not give up ever.","topic":"Ceremony","kind":"promise"}],"attacks":[{"t":341,"quote":"we fight against human traffickers who prey on poverty.","topic":"Africa infrastructure","target":"Human Traffickers"},{"t":393,"quote":"Russia as a permanent member of the Security Council cannot evade its responsibilities.","topic":"Russia-Ukraine","target":"Russia"},{"t":408,"quote":"This is why we view with grave concern the growing hybrid threats posed by Russia against Europe","topic":"Russia-Ukraine","target":"Russia"},{"t":567,"quote":"Russia's reckless attacks in the Black Sea on shipments of Ukrainian grain destined for Africa.","topic":"Iran","target":"Russia"}],"greece":[],"said":[{"topic":"UN reform","said":0.3384,"reported":0.0,"articles":0},{"topic":"AI regulation","said":0.1388,"reported":0.0,"articles":0},{"topic":"Russia-Ukraine","said":0.0876,"reported":0.0,"articles":0},{"topic":"Iran","said":0.074,"reported":0.0,"articles":0},{"topic":"Africa infrastructure","said":0.0732,"reported":0.0,"articles":0},{"topic":"Israel-Gaza","said":0.0695,"reported":0.0,"articles":0},{"topic":"European Union","said":0.0687,"reported":0.0,"articles":0},{"topic":"Global peace","said":0.068,"reported":0.0,"articles":0},{"topic":"Lebanon","said":0.0673,"reported":0.0,"articles":0},{"topic":"Ceremony","said":0.0146,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Proto Thema","date":"2026-09-25","title":"Σάλος στην Ιταλία για τη δήλωση Ταγιάνι «οι γυναίκες με μακριές φούστες γίνονται καλύτερες μητέρες»: Του απαντούν με φωτογραφίες με μίνι","url":"https://www.protothema.gr/world/article/1884349/salos-stin-italia-gia-ti-dilosi-tagiani-oi-gunaikes-me-makries-foustes-ginodai-kaluteres-miteres-tou-apadoun-me-min","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-25","title":"Σάλος στην Ιταλία με δηλώσεις-σοκ του Ταγιάνι: «Θα συμβούλευα τον γιο μου να παντρευτεί μια λιγότερο φανταχτερή γυναίκα, που φορά πιο μακριά φούστα»","url":"https://www.iefimerida.gr/kosmos/salos-stin-italia-gia-tis-diloseis-tagiani-gia-tis-gynaikes-kai-tis-foystes","tone":"critical"}],"transcript":[{"t":0,"topic":null,"text":"Now give the floor to his Excellency Antonio Tajani, Deputy Prime Minister and Minister of Foreign Affairs and International Cooperation of Italy. &gt;&gt; Mr. President, last year from this very podium, Italy's Prime Minister Giorgia Meloni recalled that 56 armed conflicts were raging across the world, the highest number since World War II. Today, those same sources put that figure at 61. It's the stark truth of the numbers. Pope Leo XIV issued a warning that Italy has made its own. We must never grow accustomed to war because first we'll become accustomed to the words, then to images, and finally to the victims."},{"t":64,"topic":"Global peace","text":"When war becomes something we grow accustomed to, peace itself risks becoming a mirage. We will not give up. Against the law of the strongest, we choose the strength of the law. Against the politics of force, we choose the force of politics. This is the message Italy brings today to the United This is the mission of Italian diplomacy, to build bridges, open new paths, and keep dialogue alive even when it seems impossible. To work for peace, prosperity and growth because growth creates prosperity, and prosperity in turn consolidates peace. Ukraine, the Middle East, the Gulf, Sudan, and the Sahel are not separate crises, nor are trade wars, AI competition, hybrid attacks, and their economic and social Nor is terrorism in all of its many forms, which we continue to fight in every corner of the world."},{"t":126,"topic":"UN reform","text":"These are all different fronts of a single profound transformation. The world order that emerged after World War II is coming It was an imperfect order. It did not prevent wars, injustice, or But today, the world balance has been disrupted, and history, which someone has declared has reached its final chapters, once again moving at a galloping pace. But every race needs a finish line. Our task cannot be to stand and watch passively the fragmentation of our world, but it must be to build a new framework of rules, responsibility, and cooperation capable of governing change. Change that can happen only through political will, through dialogue among nations, through the awareness of peoples, and through the ability of multinational multilateral institutions to rediscover a mission equal to the challenges of our time. The United Nations cannot simply record the divisions of today. It must have the ambition to imagine the future and recognize its limitations, overcome its paralysis, and reform its instruments without abandoning its deepest raison To be the place where conflict gives way to dialogue, to diplomacy, and fear to the search for shared solutions."},{"t":207,"topic":"UN reform","text":"The United Nations remains the most universal place for pursuing this aspiration. Not because it's perfect, but because no other institution can bring together around the same table such different interests, cultures, the religions, and visions of the world. It is precisely when the world is divided that the value of dialogue grows rather than diminish diminishes. It Italy believes in this institution, in its value, and its central role. We believe in peace, which remains our guiding star, the guiding principle of Italy's foreign policy. It is rooted in our history and shried in our constitution and integral to our identity. Dialogue, however, is not a sign of weakness, nor does it mean neutrality. Italy knows where it stands. Our home is Europe. Our alliance is with the West, and our values are freedom, democracy, and the dignity of every human being. Yet, belonging to the West does not mean retreating behind fortress walls. It requires us to draw on the strength of our values to engage with others, build partnerships among equals, and mend the fabric of an international system that risks descending into chaos."},{"t":278,"topic":"Africa infrastructure","text":"The European Union, the G7, and the West, of which we are proud to be part, must not be perceived as walls. They must be bridges. This is the purpose of IMEC, the economic logistics corridor designed to connect Europe with the broader Indo-Mediterranean region. &gt;&gt; The same principle guides our relationship with Africa, a strategic priority for Italy and a major partner for our century. The Mattei Plan now involves 18 countries and is built on a simple idea, not to decide for Africa, but to decide with Africa. It is not aid handed down from above, but a partnership among equals in agriculture and energy, education and training, infrastructure and in the pharmaceutical sector. Producing vaccines in Africa saves lives, strengthens health systems, creates jobs, and supports growth capable of generating stability. It is in this spirit and in defense of the right not to be forced to migrate that we fight against human traffickers who prey on poverty."},{"t":345,"topic":"Russia-Ukraine","text":"Agreements with countries of origin and transit help us combat irregular [snorts] migration while education, training, and access to employment support safe and regular migration. A world as complex as ours can be governed in only two ways. Through shared rules or through the law of the strongest. Italy has made its choice. Italy stands for rules, dialogue, and policy. That is why we have condemned and continue to condemn Russia's aggression against Ukraine. We will continue to support Ukraine um for as long as necessary while working towards a just peace and towards a future in which Russia can once again be a partner in dialogue rather than a threat to Europe. Russia as a permanent member of the Security Council cannot evade its responsibilities. A ceasefire is not a concession to the other side. It is the first step towards a European security that protects everyone, including This is why we view with grave concern the growing hybrid threats posed by Russia against Europe and why we have expressed our full solidarity with Germany following the attack on Leipzig Peace requires openness, but it also requires resolve."},{"t":425,"topic":"Israel-Gaza","text":"Dialogue without truth is weakness. Resolve without dialogue leads to a dead end. The same principle guides our approach to the Middle East. Peace can come only through a two-state solution, two peoples, two states. In Gaza, the truce has slowed the fighting but has not yet ended the suffering. There is not a minute to lose. The truce must be consolidated. Humanitarian aid must be allowed to enter without obstruction and the disarmament of Hamas must become a reality. From the very beginning, Italy has mobilized the very best of its humanitarian capabilities through food for Gaza. We have delivered food and essential supplies provided by our farmers. We have welcomed and cared for wounded and vulnerable children. We have opened our universities and research centers to young Palestinians because a future state also needs a future generation of In Lebanon, the stakes affect the entire region. The Washington agreement of 26 June opened a door."},{"t":490,"topic":"Lebanon","text":"Italy is proud to continue hosting negotiating sessions in Rome that have helped keep that door open. For decades, Italian troops have served the cause of peace in southern Lebanon through UNIFIL and have helped train the Lebanese armed forces. We have also recently approved new development projects for the area and we will continue to play our part even after the mission's mandate has come to an end. Dear [clears throat] colleagues, 61 active conflicts mean that war is advancing even far from the television And as war advances, the principles on which we have built 80 years of international relations retreat, the prohibition of the use of force, international humanitarian law, and freedom and security of navigation. Defending freedom of navigation means defending trade, jobs, growth, and where goods can move freely, weapons are less likely to do so. The Strait of Hormuz must reopen."},{"t":552,"topic":"Iran","text":"Gulf must relaunch dialogue and ask Iran to abandon any form of nuclear threat and any aggressive policy towards other countries in the region. Attacks on shipping in the Red Sea must cease as uh must uh Russia's reckless attacks in the Black Sea on shipments of Ukrainian grain destined for Africa. These crises may seem distant, but their effects reach in every household. They drive up the cost of energy, grain, bread, and fertilizers. They hurt businesses, agriculture, and families. &gt;&gt; Food security concerns us all and demands common solutions. To address this challenge, we are working side by side with United Nations Rome-based agencies, making available the best Italian expertise from agriculture and food production to satellite technologies that help reduce the use of land, water, and pesticides. Food security and water security are part of the same struggle. &gt;&gt; There can be no harvest without water. There can be no stability, uh only hunger, conflict, and migration if there is no water."},{"t":621,"topic":"AI regulation","text":"Mr. President, dear colleagues, the choice between force and politics is not confined to war. It extends to the economy, resources, and technology, to every sphere in which unrestrained power risks prevailing over the human person. Politics thus must once again take the lead in shaping change. We stand at the dawn of a technological revolution that is already reshaping the way we live, the way we work, produce, and make decisions. It's the artificial intelligence The great inventions of the past took centuries to transform the world. Artificial intelligence is doing so in a matter of years. Those who control these technologies will enjoy an enormous advantage over those who are left behind. The risk is that new inequalities, new dependencies, and new concentrations of power, or even new forms of domination will emerge. Entire professions may disappear or be transformed. Falsifying and manipulating reality will become ever more easier."},{"t":683,"topic":"AI regulation","text":"Automated systems operating without human oversight may produce extremely dangerous decisions. Pope Leo the XIV in the encyclical Magnifica Humanitas reminded us that no algorithm can take the place of human and that any technology capable of striking without seeing the face of another person lowers the moral threshold for conflict. Italy shares this vision. But governing innovation does not mean demonizing it. Artificial intelligence can open up possibilities that today are unimaginable in medicine, for example, research, education, manufacturing, and environmental protection. Every major technological advance has generated fears, but has also created opportunities and over time greater prosperity. Turning back is neither possible nor desirable, but neither can we hand over our future to technology without rules. We do not need bureaucratic cages that can only be respected by some."},{"t":747,"topic":"UN reform","text":"We need a balance between transparency, oversight, security, and the protection of intellectual property. We need to share the benefits of innovation and build mechanisms of mutual oversight. This is precisely the task of the United Nations to establish common rules before events or the strongest actors impose their The United Nations was founded in 1945 out of a world in ruins, a world that had learned a simple truth. When each of us stands alone, we all lose. 81 years later, that lesson is more relevant than The United Nations was created to prevent violence from becoming the only But to remain faithful to that mission, it must regain its ability to make decisions and above all to act. With this conviction, Italy will continue to advocate for a universal moratorium on the death penalty, a cause rooted in civilization. Rooted in civilization in the defense of life and human dignity, which we have championed for years here in this very We are also on the front line in defending individual freedom and women's rights and fighting, among other things, the abhorrent practice of female genital We"},{"t":841,"topic":"UN reform","text":"must have the courage to say it. Too often, this organization appears For far too long, its reform has been held back by competing interests. Italy wants a Security Council that is more legitimate, more representative, and more accountable to all member states. Not even a more exclusive club, but one of the pillars of the far-reaching renewal of the United Nations that we hope the new Secretary-General will want to pursue, making it capable of deciding and acting while there is still time to change the course of events. Italy has always done its part and will continue to do so. We are among the leading contributors to the United Nations budget and among the top contributing troop contributing countries. Uh we place men and women, our resources, and our expertise at the service of peace in UNIFIL and in every mission in which we participate. To all our men and women in uniform, we go will go the gratitude of the government, our institutions, and the Italian people."},{"t":912,"topic":"European Union","text":"Mr. President, dear colleagues, my generation was born on a continent that had endured two world wars and then went on to experience the longest period of peace in its history. That was not a miracle. It was a choice. The result of political action. Amid the ruins, &gt;&gt; men and women decided to pull together coal and steel rather than use them to build new guns. From that choice emerged an unprecedented endeavor, a union founded on common institutions, peace, freedom, democracy, prosperity, human rights, and the rule of law. This is the message Italy brings to New York today. Peace is not an inheritance secured once and for all. It's a responsibility that we should shoulder every day. It must be defended with resolve. It must be built with patience, and it must be pursued without ever giving up."},{"t":975,"topic":"Ceremony","text":"And we will not give up ever. Thank you. &gt;&gt; I thank the Deputy Prime Minister and Minister of Foreign Affairs and International Cooperation of Italy."}],"compare":[{"topic":"UN & its reform","share":0.3434,"mean":0.204,"rank":32,"others":170},{"topic":"Artificial Intelligence","share":0.1409,"mean":0.05,"rank":19,"others":83},{"topic":"Russia-Ukraine War","share":0.0889,"mean":0.035,"rank":25,"others":44},{"topic":"Iran","share":0.0751,"mean":0.0134,"rank":15,"others":25},{"topic":"Africa","share":0.0743,"mean":0.0232,"rank":29,"others":36},{"topic":"Israel–Palestine","share":0.0706,"mean":0.0523,"rank":51,"others":76},{"topic":"Europe","share":0.0697,"mean":0.0038,"rank":6,"others":8},{"topic":"International Law & Order","share":0.069,"mean":0.0604,"rank":64,"others":102}]};
